 routeFromHash(){let route=location.hash.slice(1)||'home';if(route==='section-courses')route='courses';if(route==='mentors')route='courses';if(route==='welcome'){State.route='welcome';this.render();return;}if(!State.registration&&route!=='register'){State.route='welcome';if(location.hash!=='#welcome')history.replaceState(null,'','#welcome');this.render();return;}if(!routeInfo().some(r=>r[0]===route))route='home';this.navigateTo(route,true);},
